area class="portal-textarea" id="seo_description" name="seo_description" rows="3">{{ old('seo_description',$category->seo_description??'') }}</textarea></div><label class="check-row field-span"><input type="checkbox" name="is_active" value="1" @checked(old('is_active',$category->is_active??true))><span>Visible on the public journal</span></label></div><div class="form-actions"><a class="portal-button" href="{{ route('admin.categories.index') }}">Cancel</a><button class="portal-button primary" type="submit">{{ $editing?'Save category':'Create category' }}</button></div></form>
